/**
 * Publication Astro Adapter
 *
 * Loads canonical publication artifacts and their validated metadata
 * into Astro-compatible structures for static rendering.
 *
 * This adapter consumes the publication artifacts generated by the
 * upstream workflow (build-publication.ts) and makes them available
 * to Astro pages without introducing competing factual sources.
 */

import { promises as fs } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import {
	type PublicationMetadata,
	type DailyIndex,
	type EditionIdentity,
	type CanonicalReferences,
	validatePublicationMetadata,
	validateDailyIndex,
	validateEditionIdentity,
	validateCanonicalReferences,
} from "./metadata.js";
import {
	getNewsletterPath,
	getResearchAuditPath,
	getListeningNarrativePath,
	getEnglishArticlesDir,
	getEnglishListeningDir,
} from "./paths.js";
import { type PublicationContentType } from "./schema.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = join(__dirname, "..", "..", "..");
const EDITIONS_BASE = join(PROJECT_ROOT, "editions");

/** Used when an edition has no daily index and therefore no navigation index. */
const EMPTY_NAVIGATION: DailyIndex["availableNavigation"] = {
	byTopic: [],
	byOrganization: [],
	byResearchDomain: [],
	bySource: [],
};

/** Load and parse a Markdown file. */
async function loadMarkdown(filePath: string): Promise<string> {
	try {
		return await fs.readFile(filePath, "utf8");
	} catch {
		return "";
	}
}

/** Load and validate JSON metadata sidecar. */
async function loadMetadata<T>(
	filePath: string,
	validator: (data: unknown) => T,
): Promise<T | null> {
	const metaPath = `${filePath}.meta.json`;
	try {
		const content = await fs.readFile(metaPath, "utf8");
		const parsed = JSON.parse(content);
		return validator(parsed);
	} catch {
		return null;
	}
}

/** Edition content loaded for Astro rendering. */
export interface EditionContent {
	editionDate: string;
	editionId: string;
	editionIdentity: EditionIdentity;
	canonicalReferences: CanonicalReferences | null;
	dailyIndex: DailyIndex | null;
	newsletter: EditionArtifact | null;
	researchAudit: EditionArtifact | null;
	listeningNarrative: EditionArtifact | null;
	englishArticles: EditionArtifact[];
	englishListening: EditionArtifact[];
	navigation: DailyIndex["availableNavigation"];
	missingArtifacts: DailyIndex["missingArtifacts"];
}

/** Individual publication artifact with content and metadata. */
export interface EditionArtifact {
	metadata: PublicationMetadata;
	content: string;
	relativePath: string;
}

/** Check if an edition directory exists. */
export async function editionExists(editionDate: string): Promise<boolean> {
	const editionDir = join(EDITIONS_BASE, `edition_${editionDate}`);
	try {
		await fs.access(editionDir);
		return true;
	} catch {
		return false;
	}
}

/** List all available edition dates. */
export async function listEditionDates(): Promise<string[]> {
	try {
		const entries = await fs.readdir(EDITIONS_BASE, {
			withFileTypes: true,
		});
		return entries
			.filter((e) => e.isDirectory() && e.name.startsWith("edition_"))
			.map((e) => e.name.replace("edition_", ""))
			.sort((a, b) => b.localeCompare(a)); // Reverse chronological
	} catch {
		return [];
	}
}

/** List all available edition dates with PUBLISHED or VALIDATED status. */
export async function listPublicEditionDates(): Promise<string[]> {
	const allDates = await listEditionDates();
	const publicDates: string[] = [];

	for (const date of allDates) {
		const edition = await loadEditionContent(date);
		if (edition) {
			// Check if at least the newsletter is VALIDATED or PUBLISHED
			const newsletterReady =
				edition.newsletter?.metadata.lifecycleStatus === "VALIDATED" ||
				edition.newsletter?.metadata.lifecycleStatus === "PUBLISHED";
			if (newsletterReady) {
				publicDates.push(date);
			}
		}
	}

	return publicDates;
}

/** Load complete edition content for a given date. */
export async function loadEditionContent(
	editionDate: string,
): Promise<EditionContent | null> {
	const editionDir = join(EDITIONS_BASE, `edition_${editionDate}`);

	try {
		await fs.access(editionDir);
	} catch {
		return null;
	}

	// Daily index (navigational metadata). Editions committed before the index
	// existed have none; that gap is reported, not hidden.
	const dailyIndexPath = join(editionDir, "index.md");
	const dailyIndex = await loadMetadata(dailyIndexPath, validateDailyIndex);

	const newsletter = await loadArtifact(getNewsletterPath(editionDate));
	const researchAudit = await loadArtifact(getResearchAuditPath(editionDate));
	const listeningNarrative = await loadArtifact(
		getListeningNarrativePath(editionDate),
	);

	const englishArticles = await loadDerivativeArtifacts(
		getEnglishArticlesDir(editionDate),
	);
	const englishListening = await loadDerivativeArtifacts(
		getEnglishListeningDir(editionDate),
	);

	let editionIdentity: EditionIdentity | null = null;
	if (dailyIndex) {
		try {
			editionIdentity = validateEditionIdentity({
				editionId: dailyIndex.editionId,
				editionDate,
				editionWindow: dailyIndex.editionWindow,
				reportingWindow: dailyIndex.reportingWindow,
			});
		} catch {
			editionIdentity = null;
		}
	}
	let canonicalReferences: CanonicalReferences | null = null;

	// The publication package is the authoritative source for identity and
	// canonical references. It stays optional so an edition without it remains
	// visible; the absence is surfaced through `missingArtifacts`.
	const packagePath = join(editionDir, "publication-package.json");
	try {
		const pkg = JSON.parse(await fs.readFile(packagePath, "utf8"));
		editionIdentity = validateEditionIdentity(pkg.editionIdentity);
		canonicalReferences = validateCanonicalReferences(
			pkg.canonicalReferences,
		);
	} catch {
		// No usable package: keep whatever the daily index provided.
	}

	if (!editionIdentity) {
		editionIdentity = await loadFallbackEditionIdentity(editionDate);
	}
	if (!editionIdentity) {
		return null;
	}

	const missingArtifacts: DailyIndex["missingArtifacts"] = dailyIndex
		? dailyIndex.missingArtifacts
		: [
				{
					contentType: "daily-index",
					language: "nl",
					reason: "Daily index (index.md) and publication package were not emitted for this edition.",
				},
			];

	return {
		editionDate,
		editionId: `edition_${editionDate}`,
		editionIdentity,
		canonicalReferences,
		dailyIndex,
		newsletter,
		researchAudit,
		listeningNarrative,
		englishArticles,
		englishListening,
		navigation: dailyIndex?.availableNavigation ?? EMPTY_NAVIGATION,
		missingArtifacts,
	};
}

/**
 * Recover edition identity from the committed fact dossier when neither the
 * daily index nor the publication package is present. Returns null when the
 * dossier is unavailable, so an identity is never invented.
 */
async function loadFallbackEditionIdentity(
	editionDate: string,
): Promise<EditionIdentity | null> {
	const dossierPath = join(
		PROJECT_ROOT,
		"data",
		"fact-dossiers",
		`edition_${editionDate}.json`,
	);

	try {
		const record = JSON.parse(
			await fs.readFile(dossierPath, "utf8"),
		) as Record<string, unknown>;
		const window = record.editionWindow as
			Record<string, unknown> | undefined;
		if (
			typeof window?.start !== "string" ||
			typeof window?.end !== "string"
		) {
			return null;
		}
		return validateEditionIdentity({
			editionId: record.editionId ?? `edition_${editionDate}`,
			editionDate,
			editionWindow: {
				editionDate,
				start: window.start,
				end: window.end,
				timezone: "Europe/Amsterdam",
				durationHours:
					typeof window.durationHours === "number"
						? window.durationHours
						: 24,
			},
			reportingWindow: {
				start: window.start,
				end: window.end,
				timezone: "Europe/Amsterdam",
			},
		});
	} catch {
		return null;
	}
}

/** Load a single canonical artifact. */
async function loadArtifact(
	relativePath: string,
): Promise<EditionArtifact | null> {
	const fullPath = join(PROJECT_ROOT, relativePath);
	const [content, metadata] = await Promise.all([
		loadMarkdown(fullPath),
		loadMetadata(fullPath, validatePublicationMetadata),
	]);

	if (!metadata || !content) {
		return null;
	}

	return {
		metadata,
		content,
		relativePath,
	};
}

/** Load all derivative artifacts from a directory. */
async function loadDerivativeArtifacts(
	dirPath: string,
): Promise<EditionArtifact[]> {
	const fullPath = join(PROJECT_ROOT, dirPath);
	const artifacts: EditionArtifact[] = [];

	try {
		const entries = await fs.readdir(fullPath, { withFileTypes: true });
		const mdFiles = entries
			.filter((e) => e.isFile() && e.name.endsWith(".md"))
			.map((e) => e.name);

		for (const file of mdFiles) {
			const artifact = await loadArtifact(join(dirPath, file));
			if (artifact) {
				artifacts.push(artifact);
			}
		}
	} catch {
		// Directory doesn't exist or is empty
	}

	return artifacts;
}

/** Get edition content for Astro getStaticPaths. */
export async function getEditionPaths(): Promise<
	{
		params: { lang: "en" | "nl"; edition: string };
		props: { editionDate: string; locale: "en" | "nl" };
	}[]
> {
	const dates = await listPublicEditionDates();
	const paths: {
		params: { lang: "en" | "nl"; edition: string };
		props: { editionDate: string; locale: "en" | "nl" };
	}[] = [];

	for (const date of dates) {
		for (const locale of ["en", "nl"] as const) {
			paths.push({
				params: { lang: locale, edition: date },
				props: { editionDate: date, locale },
			});
		}
	}

	return paths;
}

/** Get adjacent edition dates for navigation. */
export async function getAdjacentEditions(
	editionDate: string,
): Promise<{ prev: string | null; next: string | null }> {
	const dates = await listPublicEditionDates();
	const index = dates.indexOf(editionDate);

	if (index === -1) {
		return { prev: null, next: null };
	}

	// Dates are reverse chronological (newest first)
	// So index - 1 is newer (next), index + 1 is older (prev)
	return {
		prev: dates[index + 1] ?? null,
		next: dates[index - 1] ?? null,
	};
}

/** Check if an English counterpart exists for a Dutch canonical artifact. */
export function hasEnglishCounterpart(
	dutchArtifact: EditionArtifact | null,
	englishArtifacts: EditionArtifact[],
): EditionArtifact | null {
	if (!dutchArtifact) return null;

	return (
		englishArtifacts.find((e) =>
			e.metadata.relatedVariants.some(
				(v) => v.artifactId === dutchArtifact.metadata.artifactId,
			),
		) ?? null
	);
}

/** Get the language-specific edition URL. */
export function getEditionUrl(
	editionDate: string,
	locale: "en" | "nl",
): string {
	return `/${locale}/edition/${editionDate}/`;
}

/** Get the canonical URL for an edition. */
export function getCanonicalEditionUrl(
	editionDate: string,
	locale: "en" | "nl",
	site: URL | undefined,
): string {
	if (!site) return getEditionUrl(editionDate, locale);
	return new URL(getEditionUrl(editionDate, locale), site).toString();
}

/** Get alternate language URLs for an edition. */
export function getEditionAlternateUrls(
	editionDate: string,
	currentPath: string,
	site: URL | undefined,
): Array<{ lang: "en" | "nl"; url: string }> {
	return [
		{ lang: "en", url: getCanonicalEditionUrl(editionDate, "en", site) },
		{ lang: "nl", url: getCanonicalEditionUrl(editionDate, "nl", site) },
	];
}

/** Filter artifacts by lifecycle status for public display. */
export function getPublicArtifacts(
	edition: EditionContent,
	contentType: PublicationContentType,
	language: "nl" | "en",
): EditionArtifact[] {
	const allArtifacts: EditionArtifact[] = [];

	if (language === "nl") {
		switch (contentType) {
			case "newsletter":
				if (edition.newsletter) allArtifacts.push(edition.newsletter);
				break;
			case "research-audit":
				if (edition.researchAudit)
					allArtifacts.push(edition.researchAudit);
				break;
			case "listening-narrative":
				if (edition.listeningNarrative)
					allArtifacts.push(edition.listeningNarrative);
				break;
		}
	} else {
		switch (contentType) {
			case "english-derivative":
				allArtifacts.push(...edition.englishArticles);
				break;
			case "english-listening":
				allArtifacts.push(...edition.englishListening);
				break;
		}
	}

	return allArtifacts.filter(
		(a) =>
			a.metadata.lifecycleStatus === "VALIDATED" ||
			a.metadata.lifecycleStatus === "PUBLISHED",
	);
}

/** Get reading time from artifact metadata or estimate from content. */
export function getReadingTime(artifact: EditionArtifact): number {
	if (artifact.metadata.readingTimeMinutes) {
		return artifact.metadata.readingTimeMinutes;
	}
	// Rough estimate: 200 words per minute for technical content
	const wordCount = artifact.content
		.split(/\s+/)
		.filter((w) => w.length > 0).length;
	return Math.max(1, Math.round(wordCount / 200));
}

/** Get listening duration from artifact metadata or estimate. */
export function getListeningDuration(artifact: EditionArtifact): number {
	if (artifact.metadata.estimatedListeningDurationMinutes) {
		return artifact.metadata.estimatedListeningDurationMinutes;
	}
	// Rough estimate: 130 words per minute for spoken content
	const wordCount = artifact.content
		.split(/\s+/)
		.filter((w) => w.length > 0).length;
	return Math.max(1, Math.round(wordCount / 130));
}

/** Format edition date for display in a locale. */
export function formatEditionDate(
	editionDate: string,
	locale: "en" | "nl",
): string {
	const date = new Date(`${editionDate}T00:00:00`);
	return new Intl.DateTimeFormat(locale === "nl" ? "nl-NL" : "en-US", {
		weekday: "long",
		year: "numeric",
		month: "long",
		day: "numeric",
		timeZone: "Europe/Amsterdam",
	}).format(date);
}

/** Get edition window display string. */
export function formatEditionWindow(
	editionIdentity: EditionIdentity,
	locale: "en" | "nl",
): string {
	const start = new Date(editionIdentity.editionWindow.start);
	const end = new Date(editionIdentity.editionWindow.end);
	const timeFormat: Intl.DateTimeFormatOptions = {
		hour: "2-digit",
		minute: "2-digit",
		timeZone: "Europe/Amsterdam",
	};

	return `${start.toLocaleTimeString(locale === "nl" ? "nl-NL" : "en-US", timeFormat)}–${end.toLocaleTimeString(locale === "nl" ? "nl-NL" : "en-US", timeFormat)} Europe/Amsterdam`;
}
